import{_ as a,o as i,c as s,a2 as n}from"./chunks/framework.e4u2V5E7.js";const h=JSON.parse('{"title":"Code Review Playbook","description":"Engineering playbook for code review workflow","frontmatter":{"title":"Code Review Playbook","description":"Engineering playbook for code review workflow"},"headers":[],"relativePath":"playbooks/code-review.md","filePath":"playbooks/code-review.md","lastUpdated":1784485118000}'),r={name:"playbooks/code-review.md"};function t(o,e,l,d,c,p){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="code-review-playbook" tabindex="-1">Code Review Playbook <a class="header-anchor" href="#code-review-playbook" aria-label="Permalink to &quot;Code Review Playbook&quot;">​</a></h1><h1 id="playbook-code-review" tabindex="-1">Playbook: Code Review <a class="header-anchor" href="#playbook-code-review" aria-label="Permalink to &quot;Playbook: Code Review&quot;">​</a></h1><p><strong>Purpose:</strong> Standard procedure for conducting and responding to code reviews.</p><h2 id="as-a-reviewer" tabindex="-1">As a Reviewer <a class="header-anchor" href="#as-a-reviewer" aria-label="Permalink to &quot;As a Reviewer&quot;">​</a></h2><h3 id="setup-2-min" tabindex="-1">Setup (2 min) <a class="header-anchor" href="#setup-2-min" aria-label="Permalink to &quot;Setup (2 min)&quot;">​</a></h3><ol><li>Load reviewer agent: <code>@reviewer</code></li><li>Review the PR description and linked issues</li><li>Understand the feature/fix context</li></ol><h3 id="review-process-15-30-min" tabindex="-1">Review Process (15-30 min) <a class="header-anchor" href="#review-process-15-30-min" aria-label="Permalink to &quot;Review Process (15-30 min)&quot;">​</a></h3><ol><li><p><strong>Security pass</strong> (always first)</p><ul><li>Check for hardcoded secrets</li><li>Verify input validation</li><li>Check auth/authz</li></ul></li><li><p><strong>Correctness pass</strong></p><ul><li>Logic errors</li><li>Edge cases</li><li>Error handling</li></ul></li><li><p><strong>Quality pass</strong></p><ul><li>TypeScript strictness</li><li>Code organization</li><li>Naming conventions</li></ul></li><li><p><strong>Performance pass</strong></p><ul><li>Unnecessary re-renders</li><li>Missing memoization</li><li>Large bundle impact</li></ul></li><li><p><strong>Accessibility pass</strong></p><ul><li>Semantic HTML</li><li>ARIA attributes</li><li>Keyboard navigation</li></ul></li></ol><h3 id="feedback-guidelines" tabindex="-1">Feedback Guidelines <a class="header-anchor" href="#feedback-guidelines" aria-label="Permalink to &quot;Feedback Guidelines&quot;">​</a></h3><p><strong>Be specific:</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ &quot;This could be better&quot;</span></span>
<span class="line"><span>✅ &quot;Consider using useCallback here to prevent re-renders in ChildComponent&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>Provide code examples:</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ &quot;Add error handling&quot;</span></span>
<span class="line"><span>✅ Add try/catch:</span></span>
<span class="line"><span>   try {</span></span>
<span class="line"><span>     const data = await fetchData();</span></span>
<span class="line"><span>   } catch (error) {</span></span>
<span class="line"><span>     console.error(&#39;Failed to fetch:&#39;, error);</span></span>
<span class="line"><span>     setError(&#39;Failed to load data&#39;);</span></span>
<span class="line"><span>   }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>Severity calibration:</strong></p><ul><li>Critical: Security, data loss, crash → Must fix</li><li>High: Bug, performance → Should fix</li><li>Medium: Code smell → Consider fixing</li><li>Low: Style → Optional</li></ul><h3 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h3><ul><li><strong>APPROVE</strong> — No critical/high issues</li><li><strong>REQUEST_CHANGES</strong> — Critical or high issues found</li><li><strong>COMMENT</strong> — Questions or suggestions (non-blocking)</li></ul><h2 id="as-an-author" tabindex="-1">As an Author <a class="header-anchor" href="#as-an-author" aria-label="Permalink to &quot;As an Author&quot;">​</a></h2><h3 id="responding-to-review" tabindex="-1">Responding to Review <a class="header-anchor" href="#responding-to-review" aria-label="Permalink to &quot;Responding to Review&quot;">​</a></h3><ol><li>Read all comments carefully</li><li>Ask for clarification if unclear</li><li>Fix critical/high issues first</li><li>Respond to each comment (fixed / won&#39;t fix with reason)</li><li>Push fixes and re-request review</li></ol><h3 id="common-review-feedback-patterns" tabindex="-1">Common Review Feedback Patterns <a class="header-anchor" href="#common-review-feedback-patterns" aria-label="Permalink to &quot;Common Review Feedback Patterns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feedback</th><th>Action</th></tr></thead><tbody><tr><td>&quot;Add error handling&quot;</td><td>Wrap in try/catch, handle error state</td></tr><tr><td>&quot;Missing types&quot;</td><td>Add TypeScript interface, remove <code>any</code></td></tr><tr><td>&quot;Performance concern&quot;</td><td>Add memoization, check re-renders</td></tr><tr><td>&quot;Accessibility issue&quot;</td><td>Add aria-label, check keyboard nav</td></tr><tr><td>&quot;Security issue&quot;</td><td>Validate input, check auth</td></tr></tbody></table><h2 id="post-review" tabindex="-1">Post-Review <a class="header-anchor" href="#post-review" aria-label="Permalink to &quot;Post-Review&quot;">​</a></h2><ol><li>Merge after approval</li><li>Vercel auto-deploys preview</li><li>Verify preview works</li><li>Squash merge for clean history</li></ol><h2 id="related-commands" tabindex="-1">Related Commands <a class="header-anchor" href="#related-commands" aria-label="Permalink to &quot;Related Commands&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/commands/">Commands Registry</a> for commands used in this playbook.</p><h2 id="related-agents" tabindex="-1">Related Agents <a class="header-anchor" href="#related-agents" aria-label="Permalink to &quot;Related Agents&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/agents/">Agents Registry</a> for agents involved in this playbook.</p>`,28)])])}const b=a(r,[["render",t]]);export{h as __pageData,b as default};
